window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2230959d04f79374"]={"versions": [{"id": "FIG-2230959d04f79374", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (<em>Activity Diagram</em>) nach AUTOSAR-Spezifikationsstandard.\n</li><li><strong>Funktionale Einordnung:</strong> Detailliert den algorithmischen Teilschritt „Read CRC“ innerhalb der generischen Prüfroutinen <code>E2E_PXXmSourceCheck()</code> und <code>E2E_PXXmSinkCheck()</code> der AUTOSAR E2E-Methodenprofile (Foundation-Spezifikation <code>AUTOSAR_FO_PRS_E2EProtocol</code>).\n</li><li><strong>Technischer Zweck:</strong> Schutz von Client/Server-Methodenkommunikation (z. B. via SOME/IP über den E2E-Transformator). Dient der deterministischen Extraktion der übertragenen Prüfsumme aus dem serialisierten Datenstrom zur Vorbereitung des Integritätsabgleichs.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aufrufkontext / Operationen:</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXmSourceCheck()</code>: Serverseitige Verifikation eingehender Methoden-Requests.\n</li><li><code>E2E_PXXmSinkCheck()</code>: Clientseitige Verifikation eingehender Methoden-Responses.\n</li><li><code>XX</code>: Profil-Platzhalter für das konkrete E2E-Methodenprofil (z. B. <code>04m</code>, <code>07m</code>, <code>22m</code>).\n</li></ul>\n</li><li><strong>Verwendete Datenstrukturen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Data</code>: Eingangs-Bytestring (Rohdaten-Puffer/Payload als Bytestream).\n</li><li><code>ReceivedCRC</code>: Lokale Variable (Ganzzahl-Typ korrespondierend zur CRC-Breite) zur Aufnahme der extrahierten Prüfsumme.\n</li><li><code>Offset</code>: Konfigurierter Basis-Offset des E2E-Headers innerhalb von <code>Data</code> (z. B. nach vorangestellten Protokoll-Headern).\n</li><li><code>PXXMCRC_POS</code>: Profilspezifischer relativer Byte-Versatz der CRC innerhalb des E2E-Headers.\n</li><li><code>PXXMCRC_LEN</code>: Profilspezifische Länge des CRC-Feldes in Bytes (z. B. 2, 4 oder 8 Bytes).\n</li></ul>\n</li><li><strong>Adressierungsbereich:</strong>\n<ul class=\"fig-list\"><li>Startposition: Offset + PXXMCRC_POS\n</li><li>Endposition: $\\text{Offset} + \\text{PXXMCRC\\_POS} + \\text{PXXMCRC\\_LEN} - 1$\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Eintritt über den Startknoten (<em>Initial Node</em>) bei Erreichen des Teilschritts „Read CRC“ innerhalb der Prüffunktion.\n</li><li><strong>Atomare Lese-Aktion:</strong>\n<ul class=\"fig-list\"><li>Auslesen von exakt <code>PXXMCRC_LEN</code> aufeinanderfolgenden Bytes aus <code>Data</code>, beginnend bei Index Offset + PXXMCRC_POS.\n</li><li>Rekonstruktion des Integer-Werts in der lokalen Variablen <code>ReceivedCRC</code> zwingend in <strong>Big-Endian-Byte-Reihenfolge</strong> (<em>Most Significant Byte first</em>).\n</li></ul>\n</li><li><strong>Abschluss:</strong> Direkter Übergang zum Endknoten (<em>Activity Final Node</em>). Der Schritt arbeitet synchron, lokal, blockierungsfrei und löst keine Callbacks (wie Det/Dem) oder asynchronen Verzweigungen aus.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Bindung:</strong> Pflichtanforderung gemäß [PRS_E2E_01193] zur Erfüllung von [RS_E2E_08539].\n</li><li><strong>Endianness-Handhabung:</strong> \n<ul class=\"fig-list\"><li>Die Big-Endian-Vorgabe ist transportunabhängig strikt einzuhalten.\n</li><li>Auf Little-Endian-Zielplattformen (z. B. ARM Cortex-M/R/A, TriCore, x86) muss der Stack-Entwickler eine explizite Shift-Assemblierung oder ein Byte-Swapping (<code>htons</code>, <code>htonl</code>, <code>rev</code>) implementieren, um Endianness-Inkonsistenzen zu verhindern.\n</li></ul>\n</li><li><strong>Puffervalidierung / Bounds-Checking:</strong>\n<ul class=\"fig-list\"><li>Vor Ausführung dieses Schritts muss durch vorgelagerte Guard-Conditions sichergestellt sein, dass $\\text{Length}(\\text{Data}) \\ge \\text{Offset} + \\text{PXXMCRC\\_POS} + \\text{PXXMCRC\\_LEN}$, um Out-of-Bounds-Lesezugriffe im Embedded-Speicher auszuschließen.\n</li></ul>\n</li><li><strong>Parametrierung:</strong>\n<ul class=\"fig-list\"><li><code>Offset</code> entstammt der Laufzeitkonfiguration (<code>E2E_PXXmConfigType</code>), wohingegen <code>PXXMCRC_POS</code> und <code>PXXMCRC_LEN</code> unveränderliche Profilkonstanten des jeweiligen Methodenprofils darstellen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-6550c8d72cca702c", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (<em>Activity Diagram</em>) nach AUTOSAR-Spezifikationsstandard.\n</li><li><strong>Funktionale Einordnung:</strong> Detailliert den algorithmischen Teilschritt „Read CRC“ innerhalb der generischen Prüfroutinen <code>E2E_PXXmSourceCheck()</code> und <code>E2E_PXXmSinkCheck()</code> der AUTOSAR E2E-Methodenprofile (Foundation-Spezifikation <code>AUTOSAR_FO_PRS_E2EProtocol</code>).\n</li><li><strong>Technischer Zweck:</strong> Schutz von Client/Server-Methodenkommunikation (z. B. via SOME/IP über den E2E-Transformator). Dient der deterministischen Extraktion der übertragenen Prüfsumme aus dem serialisierten Datenstrom zur Vorbereitung des Integritätsabgleichs.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aufrufkontext / Operationen:</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXmSourceCheck()</code>: Serverseitige Verifikation eingehender Methoden-Requests.\n</li><li><code>E2E_PXXmSinkCheck()</code>: Clientseitige Verifikation eingehender Methoden-Responses.\n</li><li><code>XX</code>: Profil-Platzhalter für das konkrete E2E-Methodenprofil (z. B. <code>04m</code>, <code>07m</code>, <code>22m</code>).\n</li></ul>\n</li><li><strong>Verwendete Datenstrukturen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Data</code>: Eingangs-Bytestring (Rohdaten-Puffer/Payload als Bytestream).\n</li><li><code>ReceivedCRC</code>: Lokale Variable (Ganzzahl-Typ korrespondierend zur CRC-Breite) zur Aufnahme der extrahierten Prüfsumme.\n</li><li><code>Offset</code>: Konfigurierter Basis-Offset des E2E-Headers innerhalb von <code>Data</code> (z. B. nach vorangestellten Protokoll-Headern).\n</li><li><code>PXXMCRC_POS</code>: Profilspezifischer relativer Byte-Versatz der CRC innerhalb des E2E-Headers.\n</li><li><code>PXXMCRC_LEN</code>: Profilspezifische Länge des CRC-Feldes in Bytes (z. B. 2, 4 oder 8 Bytes).\n</li></ul>\n</li><li><strong>Adressierungsbereich:</strong>\n<ul class=\"fig-list\"><li>Startposition: Offset + PXXMCRC_POS\n</li><li>Endposition: $\\text{Offset} + \\text{PXXMCRC\\_POS} + \\text{PXXMCRC\\_LEN} - 1$\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Eintritt über den Startknoten (<em>Initial Node</em>) bei Erreichen des Teilschritts „Read CRC“ innerhalb der Prüffunktion.\n</li><li><strong>Atomare Lese-Aktion:</strong>\n<ul class=\"fig-list\"><li>Auslesen von exakt <code>PXXMCRC_LEN</code> aufeinanderfolgenden Bytes aus <code>Data</code>, beginnend bei Index Offset + PXXMCRC_POS.\n</li><li>Rekonstruktion des Integer-Werts in der lokalen Variablen <code>ReceivedCRC</code> zwingend in <strong>Big-Endian-Byte-Reihenfolge</strong> (<em>Most Significant Byte first</em>).\n</li></ul>\n</li><li><strong>Abschluss:</strong> Direkter Übergang zum Endknoten (<em>Activity Final Node</em>). Der Schritt arbeitet synchron, lokal, blockierungsfrei und löst keine Callbacks (wie Det/Dem) oder asynchronen Verzweigungen aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Bindung:</strong> Pflichtanforderung gemäß [PRS_E2E_01193] zur Erfüllung von [RS_E2E_08539].\n</li><li><strong>Endianness-Handhabung:</strong> \n<ul class=\"fig-list\"><li>Die Big-Endian-Vorgabe ist transportunabhängig strikt einzuhalten.\n</li><li>Auf Little-Endian-Zielplattformen (z. B. ARM Cortex-M/R/A, TriCore, x86) muss der Stack-Entwickler eine explizite Shift-Assemblierung oder ein Byte-Swapping (<code>htons</code>, <code>htonl</code>, <code>rev</code>) implementieren, um Endianness-Inkonsistenzen zu verhindern.\n</li></ul>\n</li><li><strong>Puffervalidierung / Bounds-Checking:</strong>\n<ul class=\"fig-list\"><li>Vor Ausführung dieses Schritts muss durch vorgelagerte Guard-Conditions sichergestellt sein, dass $\\text{Length}(\\text{Data}) \\ge \\text{Offset} + \\text{PXXMCRC\\_POS} + \\text{PXXMCRC\\_LEN}$, um Out-of-Bounds-Lesezugriffe im Embedded-Speicher auszuschließen.\n</li></ul>\n</li><li><strong>Parametrierung:</strong>\n<ul class=\"fig-list\"><li><code>Offset</code> entstammt der Laufzeitkonfiguration (<code>E2E_PXXmConfigType</code>), wohingegen <code>PXXMCRC_POS</code> und <code>PXXMCRC_LEN</code> unveränderliche Profilkonstanten des jeweiligen Methodenprofils darstellen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-2230959d04f79374", "to": "FIG-6550c8d72cca702c", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Aktionsknoten („Copy CRC...“):</strong> Zeilenumbruch im Beschriftungstext angepasst; <code>ReceivedCRC</code> wurde auf die zweite Zeile umgebrochen („Copy CRC from bytestring Data to local variable / ReceivedCRC in Big Endian order.“).\n</li><li><strong>Kontext-Symbol <code>E2E_PXXmSinkCheck</code>:</strong> Die Klammern <code>()</code> wurden in eine zweite Zeile unterhalb des Funktionsnamens umgebrochen (analog zur Darstellung von <code>E2E_PXXmSourceCheck</code>).\n</li></ul>"}]};
